    if word in MODIFYING_PREFIXES:
        return 0.35 if word in {'anti', 'iso'} and not separated else 0.8
    if word in {'sub', 'post', 'inter', 'counter'}:
        return 0.3 if word in {'sub', 'post'} else 0.5
    if word in FRAGMENTS:
        return 1.7 if word == 'thro' and separated else FRAGMENTS[word]
    if word in OTHER_WRITING:
        return OTHER_WRITING[word]
