        return 1.6
    if word in {'endoth', 'anthrop'}:
        return 0.9
    if word == 'ant':
        return 0.6 if separated else 0.2
    if word in ORDINARY_O_WORDS:
        return 0.0
    if word == 'ro':
        if raw.strip() == 'Ro':
            return 0.2
        return 0.55 if separated else 2.2
    if word in {'cro', 'dro', 'tro'}:
        return 2.1
    if word in {'bro', 'gro', 'stro'}:
        return 1.0 if separated else 1.8
    if word in {'rom', 'ros', 'roph'}:
        return 0.6
    if word.endswith('ro') and len(word) <= 5 and word.isalpha():
        if word[-3] in 'aeiou':
            return 0.6
        return 1.0 if separated else 1.8
    if word.endswith('ros') and word.isalpha():
        return 0.45
    if word.endswith('os') and word.isalpha():
        return 0.15
    if word.endswith('o') and len(word) > 1 and word.isalpha():
        return 0.2
    if word in {'ο', 'о'} and not separated:
        return 0.25
    return 0.0


