"""Recognize vocabulary for evidence, research and authoritative information.

The signal is lexical, not a truth assessment: even 'no evidence' is positive.
Immediate modifiers distinguish scientific research from studying a subject,
and factual information from contact details or technical data fields.
Other vocabulary is left at zero; its small, diffuse activations are omitted.
"""
READS = ()

JUDGMENTS = set('''conclusion conclusions conclude concludes concluded opinion
opinions consensus testimony proof proofs'''.split())
SUPPORT = set('support supports supported supporting unsupported'.split())
ATTRIBUTION = set('''claim claims claiming statement statements author authors
reported reporting advice professional professionals scholarly journalism'''.split())
RELIABILITY = set('''credible credibility reliable reliability authoritative
factual informative'''.split())
SOURCES = set('''article articles journal journals literature journalist
journalists news documentary knowledge fact info witness witnesses findings
recommendation recommendations recommended expertise trust truth belief beliefs
investigation investigations investigated investigating'''.split())
RESEARCH_NOUNS = set('''study studies research evidence science report reports
journal journals opinion opinions information'''.split())
SCIENTIFIC = set('scientific biomedical'.split())
MEDICAL = set('medical clinical'.split())
RECENT = set('recent latest'.split())
POSSESSIVE = set('my your his her their our its'.split())
SUBJECT_STUDY = set('''case comparative feasibility simulation graduate
undergraduate postgraduate social medieval historical scripture bible'''.split())
QUALITY_INFO = set('''accurate factual reliable credible trustworthy confirmed
false'''.split())
TECHNICAL_INFO = set('''version module product electronic license routing
business quantum account customer card file registration location transaction
payment position positional structural technical encoded semantic textual
session energy digital'''.split())


def lexical_value(word):
    if word == 'studies':
        return 1.25
    if word in ('scientific', 'scientifically'):
        return 1.05
    if word in ('evidence', 'misinformation'):
        return 1.0
    if word in ('science', 'reputable', 'trustworthy'):
        return 0.8
    if word in ('study', 'reports', 'experts'):
        return 0.65
    if word in JUDGMENTS or word in SUPPORT or word == 'report':
        return 0.55
    if word in RELIABILITY or word in ('research', 'information', 'expert', 'facts'):
        return 0.48
    if word in ATTRIBUTION or word in ('scientist', 'scientists', 'studied'):
        return 0.38
    if word in SOURCES or word in ('medical', 'evidenced', 'misconception'):
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1].strip()
    word = token.lower().lstrip('._')
    value = lexical_value(word)
    if token[:1].isupper():
        value *= 0.85

    if word in RESEARCH_NOUNS:
        if previous in SCIENTIFIC:
            value += 1.35
        elif previous in MEDICAL:
            value += 0.75
        elif previous in RECENT:
            value += 0.4
        elif previous == 'the':
            value += 0.18
        elif previous in POSSESSIVE:
            value -= 0.14
    if word in ('study', 'studies'):
        if previous in SUBJECT_STUDY:
            value *= 0.55
        elif previous in ('to', 'we', 'you', 'will', 'can', 'should'):
            value *= 0.65
    if word == 'science':
        if previous == 'computer':
            value = -0.24
        elif previous == 'political':
            value = 0.08
        elif previous == 'social':
            value = 0.34
    if word in ('information', 'info'):
        if previous in QUALITY_INFO:
            value = 1.45
        elif previous == 'contact':
            value = -0.48
        elif previous in TECHNICAL_INFO or previous == 'personal':
            value = 0.1
        elif previous == 'more':
            value = 0.39
        elif previous == 'new':
            value = 1.05
    if word == '-based' and previous == 'evidence':
        value = 1.65
    elif word == '-reviewed' and previous == 'peer':
        value = 0.73
    if first and word in ('study', 'studies', 'evidence', 'science', 'research'):
        value *= 2.2
    return (doc, word), float(value)

