ARABIC_MN = {
    'ومن': -6.8, 'فمن': -6.8, 'المن': -4.2,
    'منه': -4.3, 'منها': -3.4, 'منهم': -2.6, 'منذ': -1.6,
    'المنا': -2.2, 'المنت': -1.05, 'منع': -1.55, 'منت': -1.45,
}

