PARTICLES = {
    'из': -0.95, 'Из': -0.85, 'от': -0.15,
    'عن': -1.1, 'از': -0.4, 'در': -0.75, 'بر': -0.78,
    'から': -0.66, 'からの': -0.72, 'まで': -0.99,
    '에서': -0.61, '까지': -0.56, '부터': -0.28,
    'desde': -0.61, 'din': -0.38,
}

# Particular m/n letters or syllables across scripts, not every nasal spelling.
NASAL_FRAGMENTS = {
    'ن': -1.0, 'م': -0.44, 'ين': -0.41, 'ین': -0.52,
    'め': -1.22, 'も': -0.21, 'もの': -0.38, 'のも': -0.75,
    'モン': -0.4, 'メ': -0.2,
    '門': -0.51, '门': -0.43, '明': -0.51, '目': -0.41,
    '민': -0.5, '먼': -0.7,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    previous_words = before.split()
    previous = previous_words[-1] if previous_words else ''
    fragment = word.lstrip('._-(/')
    lower = fragment.lower()

