        if token.startswith(' '):
            value = -8.34
            if previous in ('أكثر', 'اكثر'):
                value = -4.9       # more than
            elif previous in ('رغم', 'الرغم'):
                value = -4.7       # despite
            elif previous == 'أكبر':
