        value = -0.71 if previous == 'состоит' else -1.65
    elif word == 'от' and token.startswith(' '):
        value = -0.38
    elif word in PARTICLES:
        value = PARTICLES[word]
    elif word in NASAL_FRAGMENTS:
        value = NASAL_FRAGMENTS[word]
        if token == ' ن':
            value = -0.25
        elif token == ' م':
            value = -0.34
    elif lower == 'mon':
        if not before and word in ('mon', 'Mon'):
            value = -1.65 if word == 'mon' else -1.8
        elif token == ' Mon':
