programs.haiku:
"""A comma (or other list/date separator) written straight after a number.

In layer 0 this MLP feature goes strongly negative on a comma that directly follows a digit:
"born March 21," "(4,-1)", "1985, ", "[24, ". It is a "number just ended, separator next"
detector, and its size depends on context:
  * a comma after a day of the month (a month name a few tokens back) is the most negative;
  * a comma after a number glued to a word or identifier (node1, x2, z1) is weaker;
  * a comma after a single digit is weaker than after a longer number.
Other separators right after a number (" ,", ",-", " and", ";", the CJK date marks 日 and 月)
are negative too, but less so. Everywhere else it is about zero.
"""

READS = ()

MONTHS = (
    "January", "February", "March", "April", "May", "June", "July", "August",
    "September", "October", "November", "December",
)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = toks[-1]
    if len(toks) < 2 or not toks[-2].isdigit():
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if t == ",":
        # the comma's size depends on the number just before it
        k = len(toks) - 2
        while k >= 0 and toks[k].isdigit():
            k -= 1
        ndig = len(toks) - 2 - k
        before = toks[k] if k >= 0 else ""
        if any(m in "".join(toks[max(0, k - 3):k + 1]) for m in MONTHS):
            return None, -2.05
        if before[-1:].isalpha():
            return None, -1.05
        if ndig == 1:
            return None, -1.4
        return None, -1.7
    if t in (" ,", "，", ",-", ",\\"):
        return None, -1.0
    if t in (" and", ";", "日", "月"):
        return None, -0.5
    return None, 0.0

