"""Detect names and filesystem vocabulary, rather than arbitrary proper nouns.

Most tokens predict zero. 'Name' and 'file' are strongest; path/directory,
source-folder, and structured-data format cues are weaker. Word shape
separates prose from code identifiers. A few phrase rules distinguish
computer paths, personal names, and the verb 'file'. Context resets at
document boundaries, where strong cues get a modest boost. Values are
class strengths estimated from training examples, not token-ID lookups.
"""
import re

READS = ()

# Each set is a familiar word class; strengths approximate its response.
CLASSES = (
    (0.76, {'named', 'naming', 'unnamed', 'rename', 'renamed'}),
    (0.35, {'namespace', 'namespaces', 'classname', 'keyname'}),
    (0.18, {'username', 'usernames', 'surname'}),
    (0.79, {'filename', 'filenames', 'filepath', 'filepaths',
            'dirname', 'basename', 'filesystem'}),
    (1.04, {'folder', 'folders'}),
    (0.65, {'directory', 'directories'}),
    (0.40, {'dir', 'dirs'}),
    (0.60, {'pathname', 'pathlib'}),
    (0.74, {'src'}),
    (0.72, {'ignore', 'readme', 'repo', 'shutil'}),
    (1.00, {'fichier', 'fichiers', 'arquivo', 'arquivos'}),
    (0.48, {'nom', 'nome', 'nombre', 'namen', 'имя', 'имени', 'название'}),
    (0.35, {'resolve', 'resolver', 'resolved', 'resolves'}),
)


def lexical(token):
    word = token.strip().lstrip("._-/([{<'\"=,:;@>")
    w = word.lower()
    space = token.startswith(' ')
    if w in {'name', 'names'}:
        if w == 'names':
            return 1.00
        return 1.32 if token == 'name' else (0.95 if space else 1.07)
    if w in {'file', 'files'}:
        if token.startswith(('_', '(', '\t')):
            return 0.80
        if word[0].isupper():
            return 0.98
        return 1.10 if w == 'file' else 1.22
    if w in {'path', 'paths'}:
        return 0.44 if space and w == 'path' else 0.76
    if w == 'root':
        return 0.23 if space else 0.44
    if w in {'json', 'xml', 'yaml', 'yml'}:
        return 1.17 if token.startswith('.') else 0.82
    if w in {'aml', 'xmlns', 'fxml'}:
        return 0.68
    if w == 'ml' and not token.startswith('/'):
        return 0.42
    if w.startswith('файл') or w in {'archivo', 'archivos', 'datei', 'dateien'}:
        return 0.90
    if w in {'目录', 'каталог', 'каталога', 'каталоге', 'verzeichnis'}:
        return 0.65
    if re.search(r"['\"]\.{1,2}/$", token):
        return 0.50
    if token in {'__/', '__.'}:
        return 0.50
    if token.startswith('.'):
        if w in {'mkdir', 'getcwd', 'listdir', 'splitext', 'realpath', 'resolve'}:
            return 0.70
        if w == 'tom':  # The first piece of .toml.
            return 1.10
        extensions = {
            'ini': 0.85, 'ts': 0.73, 'tsx': 0.73, 'jar': 0.38,
            'rs': 0.22, 'txt': 0.22, 'csv': 0.22, 'spec': 0.22,
            'js': 0.11,
        }
        if w in extensions:
            return extensions[w]
        if w == 'join':
            return 0.58
    for strength, words in CLASSES:
        if w in words:
            return strength
    if re.search(r'(?:Name|Names)$', word):
        return 0.67
    if re.search(r'(?:^File|File$)', word):
        return 0.70
    if word.endswith('Path'):
        return 0.60
    if '文件' in word:
        return 1.10
    if word == '名':
        return 0.95
    if '名' in word or word == '명':
        return 0.60
    return 0.0


FILE_KINDS = {
    'configuration', 'config', 'template', 'credentials', 'application',
    'assets', 'documentation', 'include',
}
COMPUTER_PATHS = {
    'relative', 'absolute', 'file', 'directory', 'search', 'import',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    w = token.strip().lower()
    value = lexical(token)
    if carry is None or carry[0] != doc:
        if value > 0.5:
            value *= 1.28
        return (doc, token), float(value)
    previous = carry[1].strip().lower()
    if w in {'file', 'files'}:
        if previous in FILE_KINDS:
            value += 0.45
        elif previous in {'text', 'data', 'digital', 'electronic'}:
            value -= 0.30
        elif w == 'file' and previous in {'to', 'you'}:
            value -= 0.45
    elif w.lstrip('_') == 'name' and previous == 'first':
        value -= 0.65
    elif w == 'names' and previous in {'package', 'resource', 'file'}:
        value += 0.40
    elif w == 'name' and previous.endswith('operator'):
        value = 0.25
    elif w in {'path', 'paths'}:
        if previous in COMPUTER_PATHS:
            value += 0.60
        elif previous in {'circular', 'total', 'life', 'hamilton', 'maximal'}:
            value = 0.0
    elif w == 'directory':
        if previous == 'working':
            value -= 0.20
        elif previous in {
            'current', 'parent', 'installation', 'install', 'workspace',
        }:
            value += 0.40
    elif w == 'l' and previous == '.tom':
        value = 0.70
    # Continue explicit naming and filesystem-location phrases.
    elif w == 'of' and previous in {'name', 'names', 'file', 'files'}:
        value = 0.30
    elif w == 'in' and previous in {
        'file', 'files', 'template', 'included', 'include',
    }:
        value = 0.40
    return (doc, token), float(value)

