# Average activation of each family, rounded from a fit on 500k positions.
STRENGTH = {"name": 1.0, "file": 1.0, "ext": 0.9, "fmt": 0.7, "path": 0.6, "pkg": 0.4}

FAMILY = {}
for _family, _words in {
    "name": ["name", "names", "名", "名称", "nombre", "이름"],
    "file": ["file", "files", "filename", "filepath", "文件", "fichier", "파일"],
    "fmt": ["json", "xml", "yaml", "yml", "typescript", "readme"],
    "path": ["path", "paths", "dir", "dirs", "directory", "folder", "src", "root"],
    "pkg": ["package", "packages", "module", "modules", "resolve", "resolved", "ignore", "rename", "named"],
}.items():
    for _w in _words:
        FAMILY[_w] = _family

EXTENSIONS = {".json", ".yml", ".yaml", ".xml", ".ts"}


def pieces(token):
    """Lower-case letter pieces of a token: 'getName' -> ['get', 'name']."""
    spaced = re.sub(r"([a-z])([A-Z])", r"\1 \2", token)
    return re.findall(r"[^\W\d_]+", spaced.lower())


def value(token):
    if token.strip() in EXTENSIONS:
        return STRENGTH["ext"]
    best = 0.0
    for piece in pieces(token):
        family = FAMILY.get(piece)
        if family is not None:
            best = max(best, STRENGTH[family])
    return best


def step(carry, prefix, upstream):
    return None, float(value(prefix.token_strings[-1]))

