"""layers.0.mlp.down_proj:2383 -- a lexical "extra / other / actual" detector.

This component fires on a small, specific set of English modifier words (and their
Chinese/Japanese counterparts) that typically sit between a determiner and a noun:
"an EXTRA fee", "ADDITIONAL funds", "the ACTUAL cost", "the EXACT time",
"PARTICULAR care", "OTHER countries", "the TOTAL", "the MOST", "INTERNATIONAL trade",
"the LATEST version", "the HIGHEST value".  It is essentially token-driven: the same
word gives about the same activation whatever comes before it, and almost every other
token gives roughly zero.

The program looks only at the newest token and returns a fixed strength for words in
three tiers, and 0 otherwise.  Stateless: no carry, no document handling needed.
"""

READS = ()

# Strongest: "extra", "additional", "actual", "exact", "international" (and Chinese/Japanese forms).
STRONG = {
    "extra", "additional", "actual", "exact", "international",
    "额外", "实际", "国际", "國際", "際",
}
# Medium: "particular", "other", "special", "total", "most", "ideal", "practical", "optimal", ...
MEDIUM = {
    "particular", "particularly", "especially", "other", "special", "total", "most",
    "ideal", "practical", "optimal", "optimum", "internationally", "其他", "总", "特别",
}
# Weak: superlatives and a few "maximum"-type words.
WEAK = {
    "highest", "lowest", "latest", "newest", "largest", "smallest", "longest", "shortest",
    "closest", "earliest", "greatest", "biggest", "widest", "youngest", "oldest",
    "nearest", "maximum", "minimum", "maximal", "usual", "dual", "residual",
}

LEVEL = {}
for word in WEAK:
    LEVEL[word] = 0.5
for word in MEDIUM:
    LEVEL[word] = 1.0
for word in STRONG:
    LEVEL[word] = 2.5


def step(carry, prefix, upstream):
    """Activation at this position: the tier strength of the newest token's word."""
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(LEVEL.get(word, 0.0))


def main():
    """Demo: print strengths for a few words."""
    for w in ["extra", "other", "highest", "table"]:
        print(w, LEVEL.get(w, 0.0))


if __name__ == "__main__":
    main()

