programs.sol:
"""A negative lexical feature centred on the syllable 'na'.

It recognises short na spellings across scripts, and the nation, nucleic-acid
and sodium word families. It also recognises nasal syllables completed by
a UTF-8 fragment; their response depends on the encoding and a preceding ー.
Most other tokens get zero; this deliberately omits small, irregular responses.
"""
READS = ()

# Nasal syllables centred on na, with nearby nai, nan, nuo and nü forms.
NA_SYLLABLES = {
    'な': -2.7, 'ナ': -3.4, '나': -4.1, 'نا': -0.9,
    '那': -3.7, '拿': -5.2, '纳': -4.1, '納': -3.6,
    '娜': -2.6, '哪': -1.3, '乃': -1.8, '男': -0.47,
    '奈': -1.6, '呐': -2.0, '挪': -1.8, '女': -0.63,
}
# These amplitudes differ from those for a character encoded in one token.
NASAL_COMPLETIONS = {
    '那': -2.75, '哪': -0.16, '納': -0.12, '女': -1.5, '難': -1.28,
    'ਣ': -1.36, 'ण': -2.3, 'ண': -2.9,  # Retroflex nasal letters (nna).
    'ナ': -5.3, 'ニ': -1.3, 'ネ': -0.8, 'ノ': -1.0, 'マ': -1.0,
}
NUCLEIC_ACIDS = {'dna': -2.55, 'rna': -1.4, 'mrna': -1.08}


def response(token):
    word = token.strip()
    lower = word.lower()
    boundary = token[:1].isspace()
    if word in NA_SYLLABLES:
        if word == '나' and boundary:
            return -5.0
        return NA_SYLLABLES[word]
    if lower == 'на':
        return -1.9 if boundary or word == 'На' else -1.1
    if lower.startswith('на') and len(lower) == 3:
        if not boundary:
            return -0.2
        return -0.9 if lower[-1] in 'бдпрй' else -0.3
    if lower == 'na':
        if word == 'NA':
            return -2.4 if boundary else -2.9
        return -2.0 if word.islower() else -2.8
    if lower in NUCLEIC_ACIDS:
        return NUCLEIC_ACIDS[lower]
    if lower == 'sodium':
        return -1.85  # Its chemical symbol is Na.
    if lower in ('gene', 'genes'):
        return -0.85 if word == 'gene' else -0.5
    if lower.startswith('nation'):
        basic = lower in ('nation', 'national', 'nations')
        return -1.2 if basic else -0.55
    if lower.startswith('na') and len(lower) == 3:
        if lower[-1] in 'prsv':
            return -1.45
        return -0.3 if lower[-1] == 'm' else -0.85
    if lower.endswith('na') and len(lower) <= 4 and not boundary:
        weak = lower in ('ina', 'anna', 'yna')
        return -0.35 if weak else -0.75
    if lower.lstrip('._').startswith('snap'):
        fragment = lower.lstrip('._')
        return -1.3 if len(fragment) == 4 else -0.35
    if word.startswith(('那', '哪', '纳', '納')) and len(word) == 2:
        return -0.25 if word[-1] in '么麼' else -0.65
    if word.startswith('拿') and len(word) == 2:
        return -2.9
    if len(word) == 2 and word.endswith('な'):
        if '\u3040' <= word[0] <= '\u309f':
            return -1.0
    if 'な' in word and len(word) <= 4:
        return -0.25
    if 'ナ' in word and len(word) <= 2:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token)
    if previous and not previous.isalpha():
        if token == 'na':
            value = -2.8
        elif token == 'на':
            value = -1.55
    if '�' in token and carry and carry[0] == document:
        # Recover a syllable completed by a split UTF-8 character.
        text = prefix.text_prefixes[-1]
        completed = text[-1:]
        if completed in NASAL_COMPLETIONS:
            value = NASAL_COMPLETIONS[completed]
            if text[-2:-1] == 'ー' and completed in 'ニネノマ':
                value -= 1.2 if completed != 'マ' else 0.95
        elif completed in NA_SYLLABLES:
            value = response(completed)
    return (document, token[-1:]), float(value)

