"""Layer-0 MLP down-projection component 2384: a token-level "na" detector.

It writes a negative value into the residual stream on tokens whose text is the
syllable "na" in any script: Latin na / NA / DNA / RNA, Cyrillic на, kana な and ナ,
Hangul 나, and Han 拿 那 纳 哪. The Han and Hangul forms are strongest. Words
starting nation/national/naval/nav/nap, and a few n-a syllables (ana, ena, ona, una),
get a weaker value. Every other token, including words that only contain "na"
(final, analysis, name), gets 0.
"""

READS = ()

NA_SINGLE = set("拿那纳納娜哪乃呐钠なナ나")
NA_BARE = {"na", "dna", "rna", "на", "sodium"}
NA_WORDS = {"nation", "national", "nations", "nationally", "naval", "nav", "navy", "nap", "snap", "nas", "nar", "nan", "nah", "nad", "nak", "nag"}
NA_WEAK = {"ana", "ena", "ona", "una", "ina", "nat"}


def token_value(text):
    raw = text.strip()
    s = raw.lower()
    if raw in NA_SINGLE:
        return -4.0
    if s in NA_BARE:
        return -2.5
    if s in NA_WORDS:
        return -1.5
    if s in NA_WEAK:
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    return carry, token_value(prefix.token_strings[-1])

