"""Predict responses on a single digit immediately following a standalone 1.

Harvested high-impact examples repeatedly show this two-token number pattern.
The following digit 9 has a consistently weaker response; digit 1 is also
weaker than the other observed digits.
"""

READS = ()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip()
    current = prefix.token_strings[-1]
    if previous != "1" or len(current) != 1 or not current.isdecimal():
        return None, 0.0
    if current == "9":
        return None, 0.2
    if current == "1":
        return None, 0.55
    return None, 0.9

