"""Negative pulses on geographical names, dominated by Europe/European.

The rule is lexical, not a detector of whole geographical passages. European
spellings and euro currency get the largest magnitudes; other continents,
countries and demonyms get smaller ones. Handle two place-name phrases and
Chinese character fragments. A secondary lexical response is 'browser'.
"""
READS = ()
COUNTRIES = set('Australia Germany Poland Spain Portugal Belgium England France '
                'Canada Italy Ireland Britain Brazil Scotland Denmark India Japan '
                'Russia Norway Ukraine Sweden Greece Netherlands Finland UK '
                'Romania China Korea Austria Switzerland'.split())
DEMONYMS = set('Australian Canadian Americans Latin Belgian Latino British '
               'Brazilian Scottish Arab'.split())
EUROPE_STEMS = set('Europ europ urope uropean европей europé europä'.split())
REGIONS = set('Mediterranean Mediterr Baltic Lisbon continent continents'.split())


def lexical_value(token):
    word = token.strip()
    lower = word.lower()
    if lower.lstrip('-') in {'europe', 'european', 'europeans'}:
        stem = lower.lstrip('-')
        strength = {'europe': 7.2, 'european': 7.5, 'europeans': 5.2}[stem]
        if word[:1].islower():
            strength *= 0.72
        if word.startswith('-'):
            strength *= 0.67
        elif not token.startswith(' '):
            strength *= 0.8 if stem == 'europe' else 0.92
        return -strength
    if word in {'欧', '歐', '欧洲', '歐洲'}:
        return -7.7
    if word in EUROPE_STEMS:
        return -4.1
    if word in {'欧美', '欧盟', '歐美', '歐盟'}:
        return -4.3
    if word in {'Europa', 'европ', '欧元', '欧冠', '欧式'}:
        return -2.9
    if word in {'EU', 'Euro', 'EURO', 'EUR', 'Eur', '.eu'}:
        return -3.0 if token.startswith(' ') or word == 'Euro' else -2.0
    if word == '€':
        return -3.0 if token.startswith(' ') else -2.3
    if lower in {'euro', 'euros'}:
        return -2.4
    if word == 'Eu':
        return -1.6
    if lower == 'eu':
        return -1.0
    if word == '£':
        return -0.6
    if lower in {'asia', 'asian'}:
        if word == 'asia' and not token.startswith(' '):
            return -0.3  # Often a word ending, rather than the continent name.
        return -2.7 if token.startswith(' ') else -2.1
    if word in {'亚洲', 'Scandin', 'Nordic', 'Euras', '非洲', '东南亚'}:
        return -2.8
    if lower in {'africa', 'african', 'africans'} or word in REGIONS:
        return -2.1
    if word in {'America', 'América', 'Americas', 'London'}:
        return -1.4
    if word in COUNTRIES or word in {'全球', '亚', '洋', '澳门', 'Atlantic', 'Pacific'}:
        return -0.9
    if word in DEMONYMS or word in {'Paris', 'NATO', 'Western', 'worldwide'}:
        return -0.6
    if word == 'American':
        return -0.3
    if lower.lstrip('(./') in {'browser', 'browsers'}:
        return -1.25
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = lexical_value(token)
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2].strip() if same_doc else ''
    if previous == 'South' and token.strip() in {'Africa', 'African'}:
        value = -1.1
    elif previous == 'New' and token.strip() == 'England':
        value = -0.3
    if token.strip() == '€' and previous.endswith('â'):
        value = -0.85  # 'â€' is usually damaged punctuation, not currency.
    if '�' in token and prefix.text_prefixes[-1][-1:] in {'欧', '歐'}:
        value = -9.5
    elif token == '洲':
        previous_char = prefix.text_prefixes[-2][-1:] if same_doc else ''
        value = -5.6 if previous_char in {'欧', '歐'} else -1.5
    return None, value

