EUROPE_STEMS = ("europ", "европ", "欧", "歐")
EU_WORDS = {"eu", "euro", "euros", "€", "uefa"}
CONTINENTS = {"asia", "asian", "africa", "african", "nordic", "baltic", "pacific",
              "atlantic", "mediterranean", "continent", "continents", "亚洲", "非洲", "亚太",
              "太平洋", "亚", "洲"}
PLACES = {"america", "americas", "australia", "germany", "england", "britain", "poland",
          "canada", "france", "italy", "spain", "portugal", "ireland", "london", "brussels",
          "scotland", "denmark", "belgium", "ukraine", "brazil", "japan", "india", "latino",
          "barcelona", "lisbon", "frankfurt", "ontario", "caribbean", "celtic", "arctic",
          "uk", "全球", "英国", "波兰", "丹麦", "澳门"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if w.startswith(EUROPE_STEMS) or s.strip() in ("欧洲", "欧盟", "欧美"):
