programs.sol:
"""Detect forward-slash separators using token shapes and local text context.

Bare slashes are strongest. Digits, repeated separators in the same field,
and URL context weaken them. Attached letters, comments, and markup are weaker
still. Unicode slash forms, double underscores, doubled backslashes, and the
adjacent delimiters }{ have related responses. Individual word/token quirks
are deliberately omitted. State resets at document boundaries.
"""
import re

READS = ()


def slash(s, field, previous, first):
    text = s.strip()
    nested = '/' in field and not s[:1].isspace()
    if set(text) == {'/'}:
        if len(text) > 1:
            return 0.82 if len(text) == 2 else 0.55
        if '\n' in s:
            return 0.75 if s.count('\n') > 1 else 1.6
        if first:
            return 1.28 if s.startswith(' ') else 1.83
        value = 2.85 - 0.45 * previous[-1:].isdigit() - 0.3 * nested
        if nested and '://' in field:
            value -= 0.55
        if not s[:1].isspace() and any(c.isupper() for c in field):
            value += 0.15
        return value
    if text.startswith('/') and text[1:].isalpha():
        word = text[1:]
        if len(word) == 1:
            value = 1.2 - 0.3 * nested
        elif len(word) == 2:
            value = 0.82 - 0.23 * nested
        else:
            value = 0.75 - 0.5 * nested
        value += 0.28 * word[0].isupper()
        return value * 0.55 if first else value
    if '://' in text:
        return 0.76
    if '//' in text:
        return 0.82 if text.count('/') == 2 else 0.55
    if '</' in text or text.startswith('/*') or text.startswith('#!/'):
        return 0.1
    if '/>' in text or '*/' in text:
        return 0.8 if '\n' in s else 1.3
    if text.endswith('/'):
        # Quotes plus dots identify quoted relative paths.
        if '.' in text and any(c in text for c in "\"'"):
            return 1.55
        return 2.3
    if '/(' in text or '/__' in text:
        return 1.8
    return 0.65


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, field, previous = (doc, '', '') if first else carry
    s = prefix.token_strings[-1]
    if '/' in s:
        value = slash(s, field, previous, first)
    elif '／' in s:
        value = 3.0
    elif any(c in s for c in '∕⁄╱⧸'):
        value = 2.5
    elif '__' in s:
        text = s.strip()
        value = 0.79 if text == '__' else 0.5 if text.endswith('__') else 0.1
    elif '\\\\' in s:
        value = 0.54
    elif s.strip() == '}{':
        value = 0.83
    else:
        value = 0.0
    field = re.split(r'\s', (field + s)[-80:])[-1]
    return (doc, field, s), float(value)

