"""An unmerged-space detector with a negative calendar-date contrast.

Separate ASCII spaces often precede numbers in the training text. Give them
a positive default, reversed after recognized months and weakened by reference
labels, approximation/time words and function words. Line breaks and code-like
contexts strengthen the response. Brief date memory and document position
adjust it further. Initial formatting and leading-space Unicode fragments
have small special cases; other current tokens predict zero.
Only preceding text is used, and state resets at document boundaries.
"""
import re
import math

READS = ()
MONTHS = set('January February March April May June July August September '
             'October November December'.split())
ABBREVIATIONS = set('Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec'.split())
OTHER_MONTHS = set('janvier février mars avril mai juin juillet août septembre '
                   'octobre novembre décembre Januar Februar März Juni Juli '
                   'Oktober Dezember enero febrero marzo abril mayo junio julio '
                   'agosto septiembre octubre noviembre diciembre января февраля '
                   'марта апреля мая июня июля августа сентября октября ноября '
                   'декабря'.split())
DATE_WORDS = MONTHS | ABBREVIATIONS | OTHER_MONTHS
MONTH_ENDINGS = tuple(MONTHS)
DATE_ENDINGS = tuple(MONTHS | ABBREVIATIONS)
LOWER_MONTHS = {m.lower() for m in MONTHS}
LABELS = set('Figure Table Chapter Section Page Example Lemma Line Rule Verse '
             'Article Volume Proposition Algorithm Problem'.split())
CODE_WORDS = set('return const let var int float double bool function def class '
                 'import code Test test param'.split())


def space_value(tail, previous, date_age):
    if tail.endswith(('\n', '\\n')):
        return 1.43
    match = re.search(r'([^\W\d_]+)\.?\Z', tail)
    word = match.group(1) if match else ''
    lower = word.lower()
    if tail.endswith(MONTH_ENDINGS):
        return -1.64
    if word in ABBREVIATIONS:
        return -0.85 if tail.endswith('.') else -1.1
    if word in OTHER_MONTHS:
        return -0.65
    if lower in LOWER_MONTHS:
        return 0.0
    if lower in {'fig', 'figs'}:
        return -0.25 if lower == 'fig' else 0.23
    if word in LABELS or lower in {'figure', 'page', 'volume', 'vol'}:
        return 0.25
    if lower in {'about', 'around', 'approximately', 'circa', 'in', 'on',
                 'during', 'early', 'late', 'aged', 'spring', 'autumn'}:
        return 0.0
    if lower in {'from', 'between', 'over', 'under', 'until', 'nearly', 'age',
                 'the', 'de', 'en', 'le', 'von'}:
        return 0.38
    if lower in {'a', 'an', 'of', 'section', 'table', 'example'}:
        return 0.54
    if lower in {'at', 'than', 'after', 'was', 'into', 'since'}:
        return 0.66
    if lower in {'to', 'for', 'with', 'by', 'has'}:
        return 0.75
    if word in CODE_WORDS or (len(word) == 1 and word.isalpha()):
        return 1.36
    s = previous.strip()
    if s == ',':
        if date_age == 1:
            return -0.95
        return 0.98 - max(0.0, 1.65 - 0.22 * date_age)
    if s in {'§', '©', '。', '：'}:
        return 0.12
    if s and set(s) <= {'#', '•', '…', '.'}:
        return 0.65 if s == '.' else 0.5
    if previous == '-':
        return 0.62
    if s in {'=', '==', ':', '.,', '–'}:
        return 0.8
    if previous == ' ' or s.isdigit():
        return 0.97
    return 1.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, age, position = '', '', 100, 0
    else:
        _, tail, previous, age, position = carry
        position += 1
    token = prefix.token_strings[-1]
    value = space_value(tail, previous, age) if token == ' ' else 0.0
    if token == ' ' and age < 12 and not tail.endswith(DATE_ENDINGS):
        word = previous.strip().lower()
        if word in {'of', 'the', 'and', 'to', 'through', 'until'}:
            value -= max(0.0, 2.25 - 0.4 * age)
        elif previous != ',' and age > 1:
            value -= 0.7 * 0.82 ** (age - 2)
    if token == ' ':
        value -= 0.32 * math.exp(-position / 14.0)
    elif token == ' \ufffd':
        value = 0.17
    if position == 0:
        value = {' ': 0.32, '#': 1.09, '\n': 0.23, '\t': -0.27}.get(token, value)
    if token.strip() in DATE_WORDS:
        age = 0
    else:
        age += 1
    return (doc, (tail + token)[-80:], token, age, position), float(value)

