"""Passive voice: the word that marks an action as done *to* the subject.

This component (layer 0, MLP down-projection feature 2398) reads only the current token.
It fires on the passive marker of many languages, the word that comes before the
participle or the agent:
  - Chinese 被 ("by"-passive): strongest on bare 被 and after an adverb (就被, 也被);
    compounds that start with 被 (被认为, 被称为, 被困) are weaker;
  - "receive / suffer" passives: Chinese 受, 遭, 受到; Japanese 受, 遭; Vietnamese bị and
    được; Thai ถูก, โดน;
  - Japanese される / られ endings;
  - German wurde, wird, werden, wurden, worden; English been and being (has been done,
    being built); French été, être; Russian быть, был, была; Spanish/Portuguese sido, sendo;
  - the disposal markers 把 and 将 ("take X and ...") at a lower level.
Everything else stays near zero, except Korean object particles 을 and 를, which are
mildly negative. Each family gets one typical size, read off the activations.
"""

READS = ()

BEI = 13.0               # bare 被
BEI_ADVERB = 11.0        # 就被, 也被
BEI_COMPOUND = 2.2       # 被认为, 被称为, 被困 ...
RECEIVE = 2.0            # 受, 遭, 受到, bị, được, ถูก, โดน
PASSIVE_ENDING = 1.4     # される, られ family
GERMAN = 1.0             # wurde, wird, werden, wurden, worden
ENGLISH = 0.8            # been, being
OTHER_AUX = 0.5          # été, être, быть, был, была, sido, sendo
DISPOSAL = 1.0           # 把, 将, 將
OBJECT_PARTICLE = -0.35  # Korean 을, 를


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if s == "被":
        return carry, BEI
    if s.endswith("被"):
        return carry, BEI_ADVERB
    if s.startswith("被"):
        return carry, BEI_COMPOUND
    if s in {"受", "遭", "受到", "遭受", "bị", "được", "ถูก", "ูก", "โดน"}:
        return carry, RECEIVE
    if s.startswith(("され", "られ")):
        return carry, PASSIVE_ENDING
    if s in {"wurde", "wird", "werden", "wurden", "worden"}:
        return carry, GERMAN
    if s in {"been", "being"}:
        return carry, ENGLISH
    if s in {"été", "être", "быть", "был", "была", "были", "sido", "sendo"}:
        return carry, OTHER_AUX
    if s in {"把", "将", "將", "将其"}:
        return carry, DISPOSAL
    if s in {"을", "를"}:
        return carry, OBJECT_PARTICLE
    return carry, 0.0

