    if broken and token.startswith("\ufffd"):
        return None, 0.024
    if broken:
        return None, 0.018

    if previous is not None and token:
        if previous.strip().lower() == "how":
            return None, 0.040
        if previous.strip().lower() == "if":
            return None, 0.029
        left = unicodedata.category(previous[-1])
        right = unicodedata.category(token[-1])
        if left == "So" and right == "So":
