    return None, 0.0

programs.sol:
"""Approximate a parenthetical-aside opening signal.

The exact token " (" is strongly negative after a title-cased word, and
somewhat less negative after an unspaced word piece. Numbers, ordinary
words, and operators get weaker values; control-flow keywords get zero.
A short text tail tracks capitalization across pieces and resets at each
new document. Other parenthesis forms and a few explicit chat delimiters
have fixed responses. Most other tokens are predicted near zero: this
intentionally omits their small, token-specific background activations.
"""
import re

READS = ()
CONTROL_WORDS = {'if', 'elif', 'while', 'switch', 'else'}
OPERATORS = set('=+-*/<>|&^')
LAST_WORD = re.compile(r'([\w-]+)[\W_]*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry

    value = 0.0003
    if token == ' (':
        text = tail.rstrip()
        match = LAST_WORD.search(text)
        word = match[1] if match else ''
        letter = bool(previous) and previous[-1].isalpha()
        if not text or text[-1] in '([{':
            value = 0.0
        elif text[-1] in OPERATORS:
            value = -0.055
        elif word in CONTROL_WORDS:
            value = 0.0
        elif word.istitle():
            value = -0.40 if letter else -0.22
            if letter and previous.strip().isupper():
                value = -0.18
        elif previous.startswith((' ', '\t', '\n')):
            value = -0.15
        elif letter:
            value = -0.29 if word.islower() else -0.35
        elif text.endswith('.'):
            value = -0.21
        else:
            value = -0.15
    elif token == '(':
        value = -0.008
    elif token == '（':
        value = -0.04
    elif token.endswith('(') and token != '(':
        # Adjacent punctuation, including Markdown links and nested groups.
        if not any(c.isalnum() for c in token):
            value = -0.13
    elif token.lstrip() == '(!':
        # Parenthesized logical negation is a distinct, positive case.
        value = 0.17

    elif token in {'<think>', '</think>'}:
        value = 0.105
    elif token == '<|im_start|>':
        value = -0.068
    elif token == '</tool_call>':
        value = 0.114
    elif token in {'<tool_response>', '</tool_response>'}:
        value = 0.054

    return (doc, (tail + token)[-100:], token), value

