programs.sol:
"""Approximate short-whitespace and catching-up responses.

Exactly two spaces are strongly negative; two spaces followed by a line break
are stronger still. Document-start effects and the preceding line break
adjust these responses. Longer padding, tab-only blank lines, two-character
nonbreaking-space runs, vertical-bar line endings, and escaped opening angle
brackets receive smaller negative responses.

A separate positive detector recognizes Chinese 赶/趕 (hurry/catch up), its
compounds and selected following particles, plus English forms of 'catch'.
Everything else is zero. State is just document position and the last token,
reset at document boundaries. Smaller, unrelated lexical responses are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    startup = 1.0 / (1 + position / 32.0)
    after_break = previous.endswith('\n')
    value = 0.0
    if s == '  ':
        value = -1.09 - 0.55 * startup + 0.12 * after_break
    elif s in {' \u00a0', '\u00a0\u00a0'}:
        value = -0.49 if s.startswith(' ') else -0.75
    elif s.isspace() and '\n' in s:
        pad = s.split('\n')[0].rstrip('\r')
        spaces, tabs = pad.count(' '), pad.count('\t')
        if tabs:
            value = -0.42 if spaces else -0.18 * min(tabs, 2)
        elif spaces == 2:
            value = -2.41 - 1.11 / (1 + position / 64.0) ** 1.5
            value += 0.42 * after_break
        elif spaces == 3:
            value = -1.52 - 0.55 / (1 + position / 64.0)
        elif spaces == 4:
            value = -0.61 - 0.37 / (1 + position / 64.0) ** 0.5
        elif spaces >= 5:
            value = -0.60 if spaces <= 7 else -0.47
        if s.count('\n') > 1:
            value *= 0.75

    # Table borders and diagnostic gutters are also line-ending markers.
    if s.strip() == '|' and '\n' in s:
        value = -0.28 if s.startswith(' ') else -0.10
        if '\r' in s:
            value -= 0.2
    elif s.strip() == '\\<':
        value = -0.30 if s.startswith(' ') else -0.44

    word = s.strip()
    if word in {'赶', '趕'}:
        value = 9.5
    elif '赶' in word or '趕' in word:
        value = 1.1 if word in {'赶紧', '趕緊', '赶快', '趕快'} else 4.5
        if word.startswith('追') or word.endswith('赴'):
            value = 3.0
    elif word.lower() in {'catch', 'catches', 'catching', 'caught', 'catcher'}:
        value = {'catch': 0.3, 'caught': 0.55, 'catcher': 0.45}.get(
            word.lower(), 0.7
        )
    elif previous.strip() in {'赶', '趕'} and word in {'上', '上了', '着', '著'}:
        value = 4.5
    return (doc, position, s), float(value)

