    'during': -0.11,
    'entre': -1.53, 'unter': -0.94, 'между': -1.05,
    'среди': -4.63, 'wśród': -4.86, 'из': -0.22,
    'بين': -1.5, 'من': -0.52, '其中': -0.61,
}
# Quantifiers and words that introduce a member, sample, or collection.
PARTITIVES = {
    'some': -2.42, 'one': -1.62, 'none': -1.4, 'any': -1.11,
    'each': -0.59, 'many': -0.62, 'most': -0.47,
    'few': -1.2, 'all': -0.26, 'half': -0.32,
    'which': -0.54, 'that': -0.32, 'out': -0.62,
    'both': -0.19, 'either': -0.4, 'neither': -0.5,
    'several': -0.54, 'much': -0.29,
    'member': -0.8, 'members': -0.51,
    'example': -0.43, 'examples': -1.04,
    'sample': -1.05, 'samples': -0.67, 'survey': -1.0,
    'list': -0.33, 'group': -0.19, 'part': -0.15, 'portion': -0.15,
}
CHASTITY_IDEOGRAPHS = {'贞', '貞'}
CARDINALS = set('two three four five six seven eight nine ten'.split())
COMPARISONS = {'difference', 'distance', 'differences', 'angle', 'association'}


def of_response(token, previous):
    word, prev = token.strip(), previous.strip()
    lower = prev.lower()
    if word == 'OF':
        return -0.17
    if word == 'Of':
        if not prev or not prev[-1].isalnum():
            return -2.15
        if lower in PARTITIVES:
            return PARTITIVES[lower] - 0.5
        return -0.7 if token[0].isspace() else -1.2
    if token == 'of':
        return -0.38
    if lower == 'some' and prev[0].isupper():
        return -3.35
    if lower in {'%', 'percent'}:
        return -0.61
    if lower.isdigit() or lower in CARDINALS:
        return -0.44
    if not prev or not prev[-1].isalnum():
        return -0.36
