        if word[0].isupper():
            value = -8.08 if token[0].isspace() else -8.63
        elif not token[0].isspace():
            value = -6.6
    elif lower == 'between' and prev in COMPARISONS:
        value = -0.4
    elif lower in {'between', 'across'} and word[0].isupper():
