def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, escape = '', ''
    if carry is not None and carry[0] == doc:
        previous, escape = carry[1:]
    token = prefix.token_strings[-1]
    value, next_escape = 0.0, ''
    if previous.endswith('\\'):
        body = previous.rstrip('\\')
        slashes = len(previous) - len(body)
        if token in ('n', 't', 'r'):
            value = {'n': -1.61, 't': -0.95, 'r': -0.55}[token]
            if slashes >= 2:
                value = {'n': -1.14, 't': -0.59, 'r': -0.34}[token]
            if slashes >= 4 and token == 'n':
                value += 0.34
            if slashes == 1:
                if token == 'n':
                    if body.isspace() or body.endswith(('.', '?')):
                        value += 0.14
                    elif body.endswith('()'):
                        value += 0.13
                    elif body.endswith((')', ',', ';')):
                        value -= 0.10
                    elif body.endswith('`'):
                        value -= 0.30
                    elif body.endswith(('"', "'")) and not body.endswith('\\"'):
                        value -= 0.18
                elif body.endswith(('"', "'")) and not body.endswith('\\"'):
                    value -= 0.25
            next_escape = 'split'
        elif token.startswith('n') and token[1:2].isupper():
            # A newline letter merged with the next capitalized word.
            value = -0.55
    if token == '\\n':
        value = -0.73
        if previous == '\\r':
            value = -1.35
        elif escape == 'split':
            value -= 0.45
        elif escape == 'fused':
            value -= 0.26
        next_escape = 'fused'
    elif token == '\\t':
        value = -0.84
        word = previous.strip()
        # A number or lone variable suggests the mathematical \times.
        if not escape and (word.isdigit() or (len(word) == 1 and word.isalpha())):
            value = -0.10
        next_escape = 'fused'
    return (doc, token, next_escape), float(value)

