"""Backslash-escape letter detector (layer 0, MLP down_proj, component 2407).

This component goes strongly negative on the letter that completes a
backslash escape written as text, such as the n of "\\n" or the t of "\\t".
It only does so when the letter directly follows a backslash, so the
escape is spelled out in source code or prose and not written as a real
newline or tab. The most negative case is a bare "n" right after a
backslash (about -1.6). Escape tokens that merge the backslash and letter
into one token ("\\n", "\\t") are about -0.8. Multi-letter tokens after a
backslash that start with n, such as "\\nabla", are weaker (about -0.3).
Everything else, including ordinary "n" and "t" letters, gives about 0.

The program is stateless: it reads only the newest token and the one
before it, and resets at a document boundary.
"""

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    else:
        prev = ""
    if tok in ("\\n", "\\t"):
        value = -0.8
    elif prev.endswith("\\"):
        if tok == "n":
            value = -1.6
        elif tok == "t":
            value = -1.2
        elif tok[:1] == "n":
            value = -0.3
        else:
            value = 0.0
    else:
        value = 0.0
    return carry, float(value)

