def continuation(root, token):
    word = token.strip().lower()
    attached = bool(token) and not token[0].isspace()
    if not any(c.isalpha() for c in word):
        return 0.0
    if root == 'heart':
        if word in {'disease', 'attack', 'attacks', 'rate', 'rates'}:
            return 1.65
        if word == 'failure' or (attached and word in HEART_ENDINGS):
            return 2.1
        if word in {'health', 'transplant', 'land', 'wood', 'iness'}:
            return 1.2
        if word in {'surgery', 'illness', 'condition', 'conditions'}:
            return 0.8
        if word.startswith('-'):
            return 1.0
        if word == 'of':
            return -0.14
        return 0.04 if word in FUNCTION_WORDS else 0.15
    if root == 'brain':
        if word == 'mass':
            return 2.8 if attached else 0.9
        if word in {'damage', 'tissue', 'cells', 'surgery', 'washing', 'power'}:
            return 1.5
        if word in {'injury', 'injuries', 'tumor', 'tumour', 'stem',
                    'wave', 'waves', 'function', 'teas', 'teaser', 'child'}:
            return 1.0
        return 0.03 if word in FUNCTION_WORDS else 0.15
    if root == 'mind':
        if word in {'set', 'sets', '-set', 'game', 'games', 'storms'}:
            return 1.35
        if word in {'less', 'fulness', 'you'}:
            return 0.95
        return 0.03
    if root in {'心', '的心'}:
        # Chinese/Japanese grammatical continuations are usually quiet.
        if word in {'的', 'の', 'で', 'である', '很', '就', '就会',
                    '是', '在', '了', '不', '也', '都', '和'}:
            return 0.03
        # 心事, 心病, 心碎: worries, illness, heartbreak.
        if word in {'事', '病', '碎'}:
            return 2.6
        if word in {'灵', '靈', '配', '所', '存', '水', '生'}:
            return 1.95
        return 0.7
    if root in {'脑', '腦'} and word in {'损伤', '損傷', '部', '电', '電'}:
        return 1.4
    if root == 'cardiovascular' and word in {'disease', 'diseases'}:
        return 1.1
    return PHRASE_STRENGTH.get(root + ' ' + word, 0.0)


