    (-0.6, 'perform performed performing performs pursue pursued pursuing'.split()),
    (-0.8, 'engage engaged engages engaging'.split()),
    (-2.6, 'undertake undertaking undertaken'.split()),
    (-1.05, 'undergo undergone undergoing underwent'.split()),
    (-0.9, 'ongoing commence commenced'.split()),
    (-1.4, 'underway embark embarked embarking'.split()),
    (-0.65, 'unfold unfolds unfolding'.split()),
    (-0.35, 'doing redo proceeding launched'.split()),
    (-0.45, 'engagement conductor'.split()),
    (-0.68, '实施 从事 を行う を行 を行い'.split()),
    (-0.5, '举行 举办 をする をして'.split()),
    (-0.9, 'пров провед проведения'.split()),
    (-0.6, 'realizar realizado realiz'.split()),
)
ACTIVITY = {w: a for a, words in ACTIVITY_FAMILIES for w in words}
ACTIVITY.update({'undert': -1.9, 'done': -0.15, '行われ': -1.1})
# Completed activity words whose last syllable is a separate token.
SPLIT_WORDS = {
    'undertook': -3.2, 'undertakes': -2.7, 'undertake': -2.7,
    'undertakings': -2.1, 'embarking': -2.5, 'embarks': -2.5,
    'commences': -2.1, 'engage': -0.8, 'conducting': -1.05,
    'conducted': -1.05, 'conducts': -1.05, 'rearrange': -0.85,
    'rearranging': -0.85, 'rearranged': -0.85,
}
CARRY = {'carry', 'carried', 'carrying', 'carries'}
QUOTE_PAIRS = {'“': '”', '„': '“', '「': '」', '『': '』'}
CLOSERS = set('"\'”’」』“')
SENTENCE_END = set('.。!?！？…')


def quote_state(active, count, s):
    """Count alphanumeric characters between matching double quotes."""
    length = None
    for c in s:
        if active and c == active:
            if length is None:
                length = count
            active, count = '', 0
        elif c in QUOTE_PAIRS:
            active, count = QUOTE_PAIRS[c], 0
        elif c == '"':
            active, count = '"', 0
        elif active and c.isalnum():
            count = min(count + 1, 500)
    return active, count, length


def quotation(s, previous, length):
    q = next((i for i, c in enumerate(s) if c in CLOSERS), -1)
    if q < 0:
        return None
    before, quote, after = s[:q], s[q], s[q + 1:]
    if any(c.isalnum() for c in after):
        return None  # opening quote attached to a word
    curly, single = quote in '”’', quote in "'’"
    if before and not before[0].isspace():
        punct = before.replace('\\', '')
        if quote == '“':  # can close a German quotation
            return {'.': 1.1, '。': 0.67, ',': 0.17, '，': 0.17}.get(punct)
        if punct in ('.', '。', ').'):
            value = (1.6 if single else 2.2) + (0.4 if single else 0.2) * curly
            value += 0.15 * (punct == '。')
        elif punct in (',', '，'):
            value = (0.6 if single else 0.93) + 0.55 * curly
        elif punct in ('!', '?', '！', '？'):
            value = (0.8 if single else 0.97) + 0.36 * curly
        elif punct in ('...', '…', '……'):
            value = 0.73
        elif punct in (':', ';'):
            value = 0.35
        else:
            return None
        if '\\' in before:
            value *= 0.6
        if after == '\n' and curly:
            value -= 0.15
        if '\n\n' in after:
            value -= 0.36 if value > 1.5 else 0.1
        if after.strip():  # code/string terminator
            value *= 0.65 if after.strip().startswith(quote) else 0.45
        if value > 1.5 and quote in '"”':
            length = 200 if length is None else length
            value += (-0.23 + 0.0075 * min(length, 70)) if '。' in s else (
                -0.45 + 0.0038 * min(length, 200))
        return value
    if not before.strip():
        if before and quote in '"\'' and not after:
            return None
        if previous and previous[-1] in SENTENCE_END:
            return 0.65 if quote in '”」' else 0.35
        if '\n' in after:
            return 0.06 if after.strip() else (0.15 if single else 0.36)
        if after.startswith(('.', '。')):
            return 0.5 if curly else 0.2
    return None


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, prev, active, count = ('', '', '', 0) if (
        carry is None or carry[0] != doc) else carry[1:]
    word = s.strip().lower()
    joined = word
    if s and s[0].isascii() and s[0].isalpha():
        if prev.isascii() and prev.isalpha() and word.isalpha():
            joined = (prev + word)[-24:]
    active, count, length = quote_state(active, count, s)
    value = quotation(s, previous, length)
    if value is None:
        value = ACTIVITY.get(word, 0.0)
        if word == 'conduct' and not s.startswith(' '):
            value = -1.3
        elif s in ('duct', 'DUCT', 'ducted'):
            value = -0.9
        elif word == 'out':
            value = -3.4 if prev in CARRY else -0.03
        elif word in ('on', 'upon') and prev.startswith('embark'):
            value = -2.9
        elif word == 'on' and prev in CARRY:
            value = -1.1
        elif word == 'in' and prev in {'engage', 'engaged', 'engaging', 'engages'}:
            value = -1.1
        elif word == 'of' and prev == 'conduct':
            value = -0.6
        elif word == 'cabo' and prev == 'a':  # llevar a cabo
            value = -1.4
        elif joined != word and joined in SPLIT_WORDS:
            value = SPLIT_WORDS[joined]
        elif s == '-on' and prev in ('hands', 'carry'):
            value = -1.9
        elif '开展' in s or '開展' in s:
            value = -3.4
        elif '展开' in s:
            value = -2.1
        elif '进行' in s or '進行' in s:
            value = -0.67
        elif word.startswith('выполн'):
            value = -0.54
        elif s.rstrip() == '.)':
            value = 0.34
    return (doc, s, joined, active, count), float(value)

