        member = s[1:]
        strength = LIBRARIES.get(p, 0.0)
        if member in {'py', 'go', 'js', 'md', 'txt', 'cpp', 'json'}:
            strength = 0.0
        elif p == 'javafx' and member in {'fxml', 'event', 'geometry', 'util'}:
            gui_packages = {'fxml': 0.6, 'event': 2.7,
                            'geometry': 4.0, 'util': 4.1}
            strength = gui_packages[member]
        if p == 'android':
            if member == 'widget':
