            elif member in {'util', 'net', 'text'}:
                strength = 6.8
        elif p == '.springframework':
            if member in {'web', 'security'}:
                strength = 6.0
            elif member in {'context', 'http', 'test', 'transaction', 'validation'}:
                strength = 3.6
            elif member == 'ui':
                strength = 1.5
        elif p == '.google' and member in {'api', 'android'}:
