        elif p == 'pd' and member in {'read', 'Series'}:
            strength = 1.6
        if s in {'.com', '.org', '.net'}:
            strength = 0.3
            if p.startswith('.') and p[1:].isalpha():
                strength = 0.9 if s == '.com' else 1.7
