    elif p in {'aws', '/aws'} and s == '-sdk':
        strength = 2.6
    elif s in {'-plugin', '-sdk', '-dev'}:
        strength = 1.0 if s == '-plugin' else 0.7
        if 'eslint' in p and s == '-plugin':
            strength = 1.9
    elif p == 'usr' and s in {'/local', '/bin'}:
        strength = 0.7
    elif p == '/wp' and s in {'-content', '-login'}:
        strength = 4.2
    elif p == 'Google':
        if s in GOOGLE_TOOLS:
            strength = 4.5
        elif s in GOOGLE_SEARCH:
            strength = 3.2
        elif s == 'Scholar':
            strength = 0.5
    elif s in PRODUCTS.get(p, ()):
        strength = 2.4
        if p == 'GitHub' and s in {'Actions', 'Pages'}:
            strength = 4.7
        elif p == 'Amazon' and s == 'Prime':
            strength = 3.8
        elif p == 'YouTube':
            strength = 1.2
    elif s in COMPOUNDS.get(p, ()):
        strength = 0.9
    elif token.startswith(' ') and p.isalpha() and p[0].isupper():
        if s in TEAM_NICKNAMES:
            strength = 2.2
        elif p == 'York' and s in {'City', 'Times', 'State'}:
            strength = 2.1
        elif s == 'City' and p in {'Mexico', 'Oklahoma'}:
            strength = 1.6
        elif s == 'University' and p in UNIVERSITY_NAMES:
            strength = 2.7 if p == 'Oxford' else 1.8
