    return (doc, token), -float(strength)

programs.haiku:
"""Layer 0, MLP down-projection, component 2416: a diffuse, token-specific feature.

Plain-terms summary: this component's output is a small signed number that depends
on which token is being read. Its variance is spread over thousands of different
tokens with no shared sign, so no short list of word classes captures it. This
program predicts only the coarse tendencies that are visible in sampled text:

  - the first token of each document: slightly negative (the model resets there);
  - tokens written in CJK script (Chinese, Japanese, Korean): slightly positive;
  - code-like tokens (identifiers with dots, slashes, brackets, or camelCase):
    slightly positive;
  - everything else: 0.

The values are the group averages measured on sampled text. They explain almost
none of the component's variance (see the explanation); a per-token table would
explain far more but is not a concept.
"""

import re

READS = ()

CODE_MARKS = re.compile(r"[._/<>{}()\[\];=]|[a-z][A-Z]")
DOC_START = -0.008
CJK = 0.003
CODE = 0.001


def is_cjk(text):
    """True if the token has a Chinese, Japanese or Korean character."""
    return any("぀" <= c <= "鿿" or "가" <= c <= "힯" for c in text)


def step(carry, prefix, upstream):
    """This token's predicted activation; `carry` is unused."""
    token = prefix.token_strings[-1]
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:
        value = DOC_START
    elif is_cjk(token):
        value = CJK
    elif CODE_MARKS.search(token):
        value = CODE
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a negative detector for written addition, not an arithmetic sum.

Plus signs dominate. Their strength depends on token spacing, prior addition,
nearby digits/letters, and whether the document has shown code or math syntax.
Increment and compound assignment have separate strengths. There are weaker
responses to assignment signs, the word plus, Chinese 加, multiplication,
and diff hunk markers. All history resets when the document changes.
"""
READS = ()
CODE = (';', 'def ', 'const ', 'var ', 'public ', '//', 'return ',
        'import ', 'function ', '#include', 'let ')
MATH = ('^', '²', '³', '\\frac', '\\sqrt', 'sqrt', '\\sum', '\\int')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, False, 0, 0)
    _, recent, previous, code, math, additions, position = carry
    token = prefix.token_strings[-1]
    symbol = token.strip()
    repetition = min(additions, 8) / 8
    age = min(position, 100) / 100
    digit = previous[-1:].isdigit()
    letter = previous[-1:].isalpha()
    value = 0.0
    if symbol == '+':
        value = (-3.40 - 0.87 * (not token.startswith(' '))
                 + 0.45 * digit + 0.20 * letter - 0.24 * code
                 + 0.46 * math + 0.33 * repetition + 0.22 * age)
        if recent.rstrip().endswith('chmod'):
            value -= 2.0
        if '\n' in token:
            value = -2.45
    elif '+' in symbol:
        if symbol == '+++':
            value = -3.55
        elif symbol == '++':
            value = -1.60 if token.startswith(' ') else -2.0
        elif '++' in symbol:
            value = -0.5
        elif '+=' in symbol:
            value = -1.45
        elif '+/-' in symbol:
            value = -0.75
        else:
            value = -2.65
    elif symbol == '=' and token.startswith(' ') and '\n' not in token:
        value = (-0.19 + 0.02 * digit - 0.07 * letter - 0.18 * code
                 + 0.12 * math + 0.11 * repetition + 0.09 * age)
    elif symbol == ':=':
        value = -0.57 if token.startswith(' ') else -0.35
    elif symbol == '＋':
        value = -3.5
    elif symbol == '加':
        value = -1.25 if not token.startswith(' ') else -0.77
    elif symbol.lower() == 'plus':
        value = -0.77
    elif symbol == '×':
        value = -0.22
    elif symbol == '@@':
        value = -0.5
    recent = (recent + token)[-100:]
    code = code or any(marker in recent for marker in CODE)
    math = math or any(marker in recent for marker in MATH)
    return (doc, recent, token, code, math,
            additions + ('+' in token), position + 1), value

