CJK_STROKE_PREFIX = 14273             # b'\xe5\xbd': U+5F40..U+5F7F
CONTINUATION_BYTES = {109: 0xB1, 229: 0x87, 247: 0x99}
EMOJI_PREFIX = 11162                 # b' \xf0\x9f': U+1F000..U+1FFFF lead


