    bare = word.lstrip('_#.(/-')
    if bare in {'region', 'regions', 'endregion'}:
        return 0.40
    if word in {'regional'}:
        return 0.04
    if 'vocabulary' in word or word == 'ocabulary':
        return -0.52
    if bare == 'vocab':
        return -0.36
    if bare in {'harvest', 'harvested', 'harvests'}:
        return -0.42
    if bare == 'harvesting':
        return -0.22
    if bare in {'exchange', 'exchanges', 'exchanged'}:
        return -0.28
    if bare in {'trade', 'trades', 'traded', 'trader', 'traders', 'trading'}:
        return -0.17
    if bare == 'inventory':
        return -0.25
    if word == '汇':
        return -3.7
    if word == '彙':
        return -2.6
    if word == '匯':
        return -2.9
    if '汇' in word:
        if word in {'词汇', '汇率'}:
            return -0.41
        if word == '汇报':
            return -0.61
        return -1.4
    if word == '晖':
        return -0.56
    if word == '荟':
        return -0.90
    if word in {'汉', '漢', '慧'}:
        return -0.52
    if word in {'武汉', '智慧'}:
        return -0.29
    if word == '地区':
        return 0.36
    if word == '地區':
        return 0.23
    if word == '交流':
        return -0.35
    if word == '交易':
        return -0.27
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, None, '', 0.0, False)
    _, previous_id, previous_text, previous_response, water_fragment = carry
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    response = lexical(s)
    if s.lower() == '#region':
        response = 1.5 if previous_id is None else 0.8
    elif s.lower() == 'region' and previous_text.rstrip().endswith('#'):
        response = 0.8
    if token == CJK_STROKE_PREFIX:
        response = -0.78
    elif token in CONTINUATION_BYTES:
        byte = CONTINUATION_BYTES[token]
        response = -0.12 if byte != 0x87 else -0.20
        if previous_id == SPACE_CJK_LEAD:
            response = -1.90 if byte == 0xB1 else -0.98
        elif byte == 0x99 and previous_id == CJK_STROKE_PREFIX:
            response = -2.60
        elif byte == 0x87 and previous_id == EMOJI_PREFIX:
            response = -0.62
    if water_fragment and token < 256 and '\ufffd' in s:
        completed = prefix.text_prefixes[-1][-1:]
        response = -4.0 if completed == '汇' else -0.95
    if s.strip().lower() == 'of':
        response += 0.56 * previous_response
    water_fragment = previous_id == SPACE_CJK_LEAD and token == 109
    return (doc, token, s, response, water_fragment), float(response)

