programs.haiku:
"""Layer-0 MLP neuron 2427 (down_proj component 2427): a C-source-code detector.

It fires on C/systems-code tokens: the comment opener "/*", the pointer arrow "->",
preprocessor lines (#define, #include, .h), C type words (int, char, void, static,
struct, sizeof, NULL, goto) and C library calls (printf, malloc, strcpy, perror...).
How strongly it fires depends on how C-like the text just before is: the share of the
last 32 tokens (same document) that contain C punctuation ; { } ( ) [ ] < > = * & # / \
or a tab or underscore. Those are the program's only inputs; everything else is predicted 0.
Measured on eval: variance explained 0.065 (r 0.26). Its e2e KL is 1.6e-5 nats/position,
against 1.8e-5 for switching the component off; CE difference 2.9e-6 (off: 5.0e-6).
"""
READS = ()

WINDOW = 32
CODE_CHARS = set("{};()[]<>=*&#/\\_\t")

COMMENT_OPEN = {"/*", "/**", "/*!", "/*\n", "/*\r\n"}
ARROW = {"->", "_->"}
PREPROC = {"#define", "#include", "#endif", "#ifndef", "#if", "#else", "#pragma", ".h"}
C_TYPE_WORDS = {"int", "char", "void", "static", "struct", "unsigned", "long", "short",
                "const", "enum", "union", "typedef", "extern", "goto", "sizeof", "NULL",
                "register", "volatile", "bool", "float", "double", "signed", "inline"}
C_LIBRARY = {"printf", "fprintf", "sprintf", "snprintf", "malloc", "calloc", "realloc", "free",
             "strcpy", "strncpy", "strcmp", "strlen", "strcat", "memset", "memcpy", "perror",
             "fopen", "fclose", "fgets", "fputs", "puts", "exit", "errno", "stderr", "stdout",
             "stdin", "argv", "argc", "socket", "bind", "listen", "accept", "htonl", "htons"}

# Typical activation when the word is C code, per group.
WEIGHT = {"comment": 2.2, "arrow": 1.2, "preproc": 1.4, "type": 0.75, "library": 0.9}


def group_of(token: str) -> str | None:
    word = token.strip().lstrip("(\t*&!").rstrip("(")
    if token.strip() in COMMENT_OPEN:
        return "comment"
    if token.strip() in ARROW or token.strip().endswith("->"):
        return "arrow"
    if token.strip() in PREPROC:
        return "preproc"
    if word in C_TYPE_WORDS:
        return "type"
    if word in C_LIBRARY:
        return "library"
    return None


def is_code(token: str) -> bool:
    return any(c in CODE_CHARS for c in token)


def step(carry, prefix, upstream):
    t = prefix.position
    group = group_of(prefix.token_strings[t])
    if group is None:
        return carry, 0.0
    # How C-like the text just before this token is (same document only).
    before = [i for i in range(max(0, t - WINDOW), t) if prefix.document_ids[i] == prefix.document_ids[t]]
    if not before:
        return carry, 0.0
    density = sum(is_code(prefix.token_strings[i]) for i in before) / len(before)
    return carry, WEIGHT[group] * density

