    if word in MATERIAL:
        return carry, -0.15
    if word in ("of", "up") and prev == "made":
        return carry, -0.8
    return carry, 0.0

programs.luna:
"""Emit weak cues for geometry and physical-object/material words, and for
"made of/up of". Positive cues cover "format", "sheet", and "talk at length".
Token pieces are joined so the word cues also catch split spellings.
"""
READS = ()

GEOMETRY = {
    "area", "surface", "sphere", "spherical", "shape", "shaped", "angular",
    "angle", "sector", "circle", "circular", "cylinder", "cube", "square",
    "symmetrical", "diameter", "radius", "triangle", "rectangular", "oval",
    "l-shaped", "tubular", "tube", "rod", "shaft", "pipe", "pipes", "ball",
    "tray", "nail", "iron", "brick", "hollow", "base", "field", "volume",
    "面积", "形", "球", "圆", "表面", "铁", "钉",
    "pyramid", "cone", "irregular", "side", "sides", "section", "sections",
    "span", "metallic", "aluminum", "steel", "ellipse",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, word = (), ""
    else:
        _, recent, word = carry
    raw = prefix.token_strings[-1]
    if any(ch.isspace() for ch in raw):
        if word:
            recent = (recent + (word,))[-2:]
        word = raw.split()[-1].lower() if raw.split() else ""
    elif raw and ("\u3400" <= raw[0] <= "\u9fff"):
        if word:
            recent = (recent + (word,))[-2:]
        word = raw.lower()
    else:
        word += raw.lower()

    value = -0.55 if word in GEOMETRY else 0.0
    if word.endswith(("spherical", "shaped", "angular", "metrical", "tubular")):
        value = -0.55
    if word in {"of", "up"} and recent and recent[-1] == "made":
        value = -0.80
    if word == "of" and len(recent) == 2 and recent == ("made", "up"):
        value = -0.80
    if word == "length" and len(recent) >= 2 and recent[-2:] == ("talk", "at"):
        value = 0.60
    if word == "format":
        value = 0.55
    if word == "sheet":
        value = 0.55
    return (doc, recent, word), float(value * 0.35)

"""Estimate a sparse signal for frequency, likelihood, and application words.

The component rises on a few ordinary words in those semantic groups; most
tokens get zero. This intentionally uses recognizable whole-token cues rather
than treating every ``-ly`` ending as a match.
"""

READS = ()

FREQUENCY = {
    "often", "usually", "regularly", "normally", "seldom", "mostly",
    "always", "frequently", "commonly", "generally", "typically",
    "occasionally", "sometimes", "conventionally", "popular", "popularly",
    "majority", "consistent", "consistently",
}
LIKELIHOOD = {
    "likely", "unlikely", "probable", "probably", "apparent",
    "conspicuous", "familiar", "obvious", "evident", "see", "sees",
    "seeing", "cited",
}
APPLICATION = {
    "use", "uses", "used", "using", "usage", "utility", "使用", "用",
    "使用する", "使用され", "사용", "사용된", "kullanılan", "usar", "veces",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.strip(".,;:!?()[]{}\"'“”‘’")
    if word in APPLICATION:
        value = 0.9
    elif word in FREQUENCY:
        value = 0.8
    elif word in LIKELIHOOD:
        value = 0.55
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate a lexical documentation-boundary signal.

Large negative estimates mark block-comment and triple-quote endings.
Their strength depends on inline versus standalone syntax and fused line
breaks. Python signatures, assignments, and remembered quote state help
identify openings; numbered listings weaken the opening estimate.
Call-argument text blocks have weaker estimates than Python docstrings.
Smaller rules cover XML/HTML documentation, JSON quotes, and chat markers.
Other tokens get zero. The short lexical memory resets between documents.
These rules capture conspicuous syntax responses, not ordinary-word variation.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, quote, block_lines, position = '', None, None, 0
    else:
        _, tail, quote, block_lines, position = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if '*/' in token and not token.endswith('*.'):
        line = re.sub(r'^\s*\d+\t', '', tail.rsplit('\n', 1)[-1])
        inline = bool(line.strip())
        if block_lines == 0 and inline:
            value = -2.25 if '\n' in token else -2.7
        elif inline:
            value = -3.35
        else:
            value = -3.8 if block_lines is not None else -4.1
        if token.strip().startswith('**/'):
            value = -4.6
        if ';' in token or '}' in token:
            value = -2.5
        block_lines = None
    elif '"""' in token or "'''" in token:
        delimiter = '"""' if '"""' in token else "'''"
        lines = tail.split('\n')
        numbered = bool(re.match(r'^\s*\d+\t', lines[-1]))
        line = re.sub(r'^\s*\d+\t', '', lines[-1]).strip()
        line = line.removeprefix('+').removeprefix('-').strip()
        before = (line + token.split(delimiter)[0]).strip()
        previous_lines = [re.sub(r'^\s*\d+\t', '', s).strip()
                          for s in lines[:-1]]
        previous = next((s.lstrip('+-').strip() for s in
                         reversed(previous_lines) if s.strip('+- ')), '')
        context = before or previous
        signature = bool(re.search(r'\)\s*(?:->[^:]+)?\s*:$', context))
        signature |= context.startswith('class ') and context.endswith(':')
        assigned = bool(re.search(r'[=(]\s*[rfub]*$', before))
        argument = before.endswith('(') or (not before and previous.endswith('('))
        known_quote = quote is not None and quote[0] == delimiter
        # A fresh signature resynchronizes state after a truncated docstring.
        opening = signature or assigned or argument or (not known_quote and (
            (position < 3 and not token.startswith(' ')) or
            (not before and previous.startswith(('#', 'from ', 'import ')))
        ))
        if tail.endswith(delimiter):
            value = 0.5
            quote = None
        elif opening:
            value = 1.2 if assigned or not token.startswith(' ') else 2.5
            if numbered:
                value = 0.8 if '\n' not in token else -0.2
            if argument:
                value = -0.5
            quote = (delimiter, argument)
        else:
            value = -4.5 if token.startswith(' ') else -3.5
            if token.startswith('.'):
                value = -5.7 if delimiter == '"""' else -4.0
            elif '\n' not in token:
                value = -1.7
            elif token.startswith(' ') and token.count('\n') >= 2:
                value = -5.5
            if known_quote and quote[1]:
                value = -2.7
            elif position < 8 and not before and not previous:
                value = -3.0
            quote = None
    elif '-->' in token:
        value = -1.9 if '\n' in token else -0.25
    elif token == ' "':
        if tail.endswith('name":'):
            value = 0.56
        else:
            value = 0.24 if tail.endswith(':') else 0.025
    elif token in ('summary', 'param', 'span', 'div', 'p'):
        closing = tail.endswith('</')
        opening_tag = tail.endswith('<') and not closing
        if closing or opening_tag:
            if token == 'summary':
                value = -1.3 if closing else 1.55
            elif token == 'param':
                value = -1.7 if closing else -0.7
            elif closing:
                value = -1.1 if token == 'span' else -0.5
            elif token == 'p':
                value = 0.65
        elif token == 'param' and tail.endswith('@'):
            value = -0.3
    elif token in ('>\n', '>\r\n') and re.search(
            r'</(?:summary|param|returns)$', tail):
        value = -2.0
    elif token == '\n\n' and tail.endswith(('<think>', '</think>',
                                                '<tool_response>')):
        value = -0.16
    elif token in ('<tool_call>', '</tool_call>'):
        value = 0.135 if token == '<tool_call>' else -0.18

    if '/*' in token and '*/' not in token:
        block_lines = token.count('\n')
    elif block_lines is not None:
        block_lines += token.count('\n')
    return (doc, (tail + token)[-600:], quote, block_lines, position + 1), value

programs.luna:
"""Approximate sparse responses to code-comment and docstring boundaries.

The strongest cue is the end of a C-style block comment or Python triple-quoted
docstring.  It also marks a docstring's opening and the tool-name string in a
tool-call JSON object; ordinary positions are zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, triple = "", ""
    else:
        _, tail, triple = carry

    context = tail + token
    value = 0.0

    # Triple-quoted strings in source code, especially function docstrings.
    for quote in ('"""', "'''"):
        start = 0
        while True:
            at = token.find(quote, start)
            if at < 0:
                break
            if triple == quote:
                value -= 2.5
                triple = ""
            else:
                before = tail.rstrip()
                line = before.rsplit("\n", 1)[-1].strip()
                looks_like_start = (
                    (not before and prefix.position == 0)
                    or line.startswith("#!")
                    or line.endswith((":", "=", "(", "[", "{"))
                )
                if looks_like_start:
                    value += 0.8
                    triple = quote
                else:
                    # A row may begin in the middle of a docstring, hiding its
                    # opening quote; plain prose before a quote suggests an end.
                    value -= 2.5
                    triple = ""
            start = at + 3

    # C, C++, Java and similar block-comment boundaries.
    if "/**" in token and "*/" not in token:
        value += 0.1
    if "*/" in token:
        value -= 3.7

    # In tool-call JSON, the quoted tool name is a smaller positive cue.
    call = tail.rfind("<tool_call>")
    if call >= 0 and token.lstrip().startswith('"'):
        recent = tail[call:]
        if recent.rstrip().endswith('"name":'):
            value += 0.55
        elif recent.rstrip().endswith('"command":'):
            value += 0.2

    return (doc, context[-500:], triple), float(value)

programs.sol:
"""A short-range numeral-pattern response, otherwise close to zero.

The strongest negative response is the second digit of 11--19 or 20,
including such pairs inside longer numbers. Separators weaken this effect.
Five is positive away from these pairs. Written teen numbers have a smaller
negative response too. Decimal digit glyphs use the same digit rules.
English number words and several Chinese numeral forms are also handled.
Only two previous tokens are kept, resetting at document boundaries.
"""
import unicodedata

READS = ()
AFTER_ONE = (0.05, -0.69, -1.78, -2.90, -3.36,
             -3.22, -3.73, -3.90, -3.83, -3.65)
BASE_DIGIT = (0.02, -0.02, 0.01, -0.03, -0.02,
              0.43, 0.01, 0.02, 0.02, -0.01)
SEPARATORS = {'.': 0.31, ' ': 0.22, ':': 0.12,
              ',': 0.18, '-': 0.07, '/': 0.06}
TEENS = set('thirteen fourteen sixteen seventeen eighteen nineteen'.split())
ORDINAL_TEENS = set(('eleventh twelfth thirteenth fourteenth fifteenth '
                     'sixteenth seventeenth eighteenth nineteenth').split())
NUMBER_WORDS = {
    'eleven': -0.77, 'twelve': -0.89, 'fifteen': -0.97,
    'five': 0.59, 'fifth': 0.36, 'fifty': 0.39,
    'three': 0.06, 'four': 0.09, 'twenty': -0.20,
    'twentieth': -0.74, 'hundred': -0.15,
}
CJK_DIGITS = '零一二三四五六七八九'


def decimal_token(s):
    if len(s) == 1 and s.isdecimal():
        return str(unicodedata.decimal(s))
    return s


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    raw = prefix.token_strings[-1]
    token = decimal_token(raw)
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        value = BASE_DIGIT[digit]
        if previous == '1':
            value = AFTER_ONE[digit]
            if digit >= 2:
                if before == '1':
                    value *= 1.15
                elif before == '0':
                    value *= 1.03
                elif before and before in '23456789':
                    value *= 0.92
        elif previous == '2' and token == '0':
            value = -1.68
        elif previous == '2' and token == '1':
            value = -0.32
        elif previous == '3' and token == '0':
            value = -0.26
        elif before == '1' and previous in SEPARATORS:
            value += SEPARATORS[previous] * (
                AFTER_ONE[digit] - BASE_DIGIT[digit])
        elif token == '5':
            if previous in (' ', '0'):
                value = 0.55
            elif previous and previous in '23679':
                value = 0.31
        elif previous == ' ' and digit >= 3:
            value += 0.06
        elif previous and previous in '679' and digit >= 3:
            value -= 0.08
    elif token == '.' and previous == '1':
        value = 0.23
    else:
        word = token.strip().lower()
        if word in NUMBER_WORDS:
            value = NUMBER_WORDS[word]
        elif word in TEENS:
            value = -1.20
        elif word in ORDINAL_TEENS:
            value = -1.07
        elif token in ('teen', 'teenth', 'eenth', 'irteen'):
            value = -1.10
        elif word in ('third', 'fourth', 'sixth', 'seventh',
                      'eighth', 'ninth', 'tenth'):
            value = -0.16
        elif token in ('²', '³'):
            value = -0.09 if token == '²' else -0.13
        elif len(word) >= 2 and word[0] == '十' and word[1] in CJK_DIGITS[1:]:
            digit = CJK_DIGITS.index(word[1])
            value = -1.0 if digit == 1 else -1.2 if digit == 2 else -1.5
        elif word and word[0] in CJK_DIGITS and word[1:] in ('', '年', '月', '日'):
            digit = CJK_DIGITS.index(word[0])
            if previous.endswith('一') and digit >= 2:
                value = 0.5 * AFTER_ONE[digit]
            elif digit == 5:
                value = 0.65
    return (doc, token, previous), float(value)

programs.luna:
"""A sparse number-pattern sketch: a few digit pairs get fixed responses; others are quiet."""

READS = ()

AFTER_ONE = {
    "2": -1.8,
    "3": -0.45,
    "4": -3.5,
    "5": -3.4,
    "6": -3.7,
    "7": -4.2,
    "8": -3.8,
    "9": -3.7,
}


def step(carry, prefix, upstream):
    pos = prefix.position
    token = prefix.token_strings[pos]
    if len(token) != 1 or token not in "0123456789":
        return None, 0.0

    previous = ""
    if pos and prefix.document_ids[pos - 1] == prefix.document_ids[pos]:
        previous = prefix.token_strings[pos - 1]

    if previous == "1" and token in AFTER_ONE:
        return None, float(AFTER_ONE[token])
    if previous == "2" and token == "0":
        return None, -1.7
    if previous == "." and token == "5":
        return None, -0.7
    if previous == "." and token == "7":
        return None, -1.2
    if token == "5":
        return None, 0.45
    return None, 0.0
